-- English source rows for the localization tables (run after snow dcm deploy).

USE WAREHOUSE TAROT_WH;
USE SCHEMA TAROT.APP;

MERGE INTO TAROT.APP.LANGUAGES t
USING (SELECT column1 AS LANGUAGE_CODE, column2 AS NAME, column3 AS NATIVE_NAME FROM VALUES
    ('en', 'English', 'English'),
    ('ru', 'Russian', 'Русский')
) s ON t.LANGUAGE_CODE = s.LANGUAGE_CODE
WHEN MATCHED THEN UPDATE SET NAME = s.NAME, NATIVE_NAME = s.NATIVE_NAME
WHEN NOT MATCHED THEN INSERT (LANGUAGE_CODE, NAME, NATIVE_NAME, ENABLED)
    VALUES (s.LANGUAGE_CODE, s.NAME, s.NATIVE_NAME, TRUE);

