-- Drop texts whose id no longer exists, and translations of texts whose
-- English changed, so translate_language.sql re-translates them.
DELETE FROM TAROT.APP.UI_TEXT t
WHERE NOT EXISTS (SELECT 1 FROM UI_TEXT_EN_SEED s WHERE s.UI_ID = t.UI_ID);

DELETE FROM TAROT.APP.UI_TEXT t
USING TAROT.APP.UI_TEXT e, UI_TEXT_EN_SEED s
WHERE t.LANGUAGE_CODE <> 'en'
  AND e.LANGUAGE_CODE = 'en' AND e.UI_ID = t.UI_ID
  AND s.UI_ID = t.UI_ID AND s.CONTENT <> e.CONTENT;

MERGE INTO TAROT.APP.UI_TEXT t
USING UI_TEXT_EN_SEED s ON t.UI_ID = s.UI_ID AND t.LANGUAGE_CODE = 'en'
WHEN MATCHED AND t.CONTENT <> s.CONTENT THEN UPDATE SET CONTENT = s.CONTENT
WHEN NOT MATCHED THEN INSERT (UI_ID, LANGUAGE_CODE, CONTENT) VALUES (s.UI_ID, 'en', s.CONTENT);

MERGE INTO TAROT.APP.CARDS t
USING (SELECT column1 AS CARD_ID, column2 AS NAME, column3 AS ARCANA, column4 AS RANK,
              column5 AS KEYWORDS, column6 AS MEANING, column7 AS UPRIGHT, column8 AS REVERSED FROM VALUES
    (1, 'The Fool', 'Major Arcana', '0', 'Beginnings · Innocence · Spontaneity · Faith', 'A fresh start taken on pure faith, stepping into the unknown with an open heart.', 'The Fool heralds a genuine new beginning. Opportunities arrive without warning and the only requirement is the courage to say yes. Travel, leaps of faith and untried paths are favoured; the universe rewards your willingness to begin before every detail is certain.', 'Reversed, The Fool warns of recklessness rather than trust. A step is being taken without preparation, or an old fear of leaping keeps you frozen at the cliff''s edge. Consider which of the two applies, and either pause for planning or accept that no journey ever feels safe.'),
    (2, 'The Magician', 'Major Arcana', 'I', 'Manifestation · Willpower · Skill · Resourcefulness', 'The power to turn intention into reality through focused will and talent.', 'Every tool you need is already on the table. The Magician appears when a desire is ready to be shaped into something concrete through clear speech, decisive action and concentrated effort. Speak your intention aloud and begin; the energy of creation flows through you now.', 'The Magician reversed points to scattered energy, deception or unused talent. Someone may be manipulating a situation, or you are distracting yourself from the one action that matters. Realign your words with your truth before you commit.'),
    (3, 'The High Priestess', 'Major Arcana', 'II', 'Intuition · Mystery · Inner voice · Secrets', 'Deep intuitive knowledge that asks to be trusted rather than explained.', 'The answer you seek is not in any outer voice but in the quiet beneath it. The High Priestess counsels stillness, listening and patience; dreams, coincidences and gut feelings carry real information now. Not everything needs to be revealed to be known.', 'Reversed, she signals ignored intuition and secrets that corrode. You may be rationalising away what you already feel to be true, or withholding your inner knowledge from those who deserve it. Return to silence and let the inner voice re-establish itself.'),
    (4, 'The Empress', 'Major Arcana', 'III', 'Abundance · Nurture · Creativity · Sensuality', 'Fertile, creative energy that grows whatever receives patient care.', 'The Empress is the great mother of the deck: abundance, comfort and creative fruit. Projects, relationships and even the body flourish under gentle, consistent attention. Say yes to pleasure, beauty and generosity — growth is your natural state right now.', 'Reversed, The Empress warns of creative blockage or smothering care. Something is being overwatered and under-pruned, or your own needs have been left off the list. Tend to yourself first and growth will resume.'),
    (5, 'The Emperor', 'Major Arcana', 'IV', 'Authority · Structure · Discipline · Stability', 'Order imposed on chaos through disciplined leadership and clear boundaries.', 'The Emperor brings structure, strategy and steady command. This is a moment for systems, rules and long-term plans rather than impulse. Authority is available to you — claim it calmly, set boundaries, and protect what you are building.', 'Reversed, the Emperor shows rigid control, tyranny or an absent father-figure. Structure has become a cage, or authority is being exercised without wisdom. Loosen the grip and lead by service rather than force.'),
    (6, 'The Hierophant', 'Major Arcana', 'V', 'Tradition · Teaching · Institutions · Belief', 'Time-tested knowledge handed down through teachers, ritual and tradition.', 'The Hierophant honours tradition, apprenticeship and the wisdom of institutions. Learning from a teacher, joining a community or following established practice will serve you now. Not every path needs to be invented; some have already been mapped.', 'Reversed, he warns of dogma, rebellion for its own sake, or outgrown beliefs. An inherited rule no longer fits your truth. Question authority respectfully and write your own creed.'),
    (7, 'The Lovers', 'Major Arcana', 'VI', 'Union · Choice · Harmony · Values', 'A significant union or a heart-led choice between paths.', 'The Lovers speak of deep connection — romantic or collaborative — and of the choices that define who we are. Alignment between your values and your actions brings harmony. When a choice appears, let the heart and the conscience decide together.', 'Reversed, The Lovers indicate disharmony, avoidance of a necessary choice, or values out of alignment with behaviour. A relationship or commitment may need honest renegotiation before it can flourish again.'),
    (8, 'The Chariot', 'Major Arcana', 'VII', 'Determination · Victory · Control · Direction', 'Opposing forces harnessed to a single will, driving toward victory.', 'The Chariot is momentum with a destination. Conflicting demands are reconciled through focus and discipline, and the road opens ahead of you. Take the reins, assert your direction and expect progress — hard-won, deliberate and public.', 'Reversed, the Chariot veers. Aggression replaces drive, or too many destinations pull the reins apart. Slow the vehicle, choose one road, and remember that control begins with self-mastery.'),
    (9, 'Strength', 'Major Arcana', 'VIII', 'Courage · Compassion · Patience · Inner power', 'True strength as gentle courage that tames the wild without breaking it.', 'Strength shows power expressed as patience, kindness and steady nerve. The lion is not defeated but befriended. Face the intimidating situation with a calm heart, and your gentleness will prove stronger than any force.', 'Reversed, Strength flags self-doubt, raw impulse or courage spent on the wrong battle. The inner beast is driving instead of being guided. Breathe, forgive yourself, and reclaim the quiet authority you actually possess.'),
    (10, 'The Hermit', 'Major Arcana', 'IX', 'Introspection · Solitude · Guidance · Wisdom', 'Withdrawing to seek truth by one''s own inner lamp.', 'The Hermit calls for deliberate retreat from noise. Solitude, study and honest self-examination reveal what crowds have hidden. The answers belong to you alone for now; share them when the lamp has burned steady.', 'Reversed, the Hermit warns of isolation that has outlived its purpose, or of hiding behind wisdom to avoid living. Come down from the mountain; the world and its lessons are waiting.'),
    (11, 'Wheel of Fortune', 'Major Arcana', 'X', 'Cycles · Destiny · Turning point · Luck', 'The great wheel turns and circumstances change with it.', 'The Wheel turns in your favour. A cycle completes and a new one begins, often with surprising speed. Coincidences are meaningful; ride the momentum and stay flexible, because the highest point of the wheel is already in motion.', 'Reversed, the Wheel resists. Bad timing, repeating patterns or luck running against the plan suggests fighting the current. Loosen your hold on outcomes; the wheel always turns again.'),
    (12, 'Justice', 'Major Arcana', 'XI', 'Fairness · Truth · Law · Cause and effect', 'Clear-eyed accountability: every effect traces honestly to its cause.', 'Justice cuts through wishful thinking with clarity and fairness. Contracts, decisions and disputes resolve according to their true merit. Act with integrity and the judgement will land in your favour; the scales are weighing things exactly as they are.', 'Reversed, Justice shows imbalance, bias or an avoided reckoning. Someone is not telling the whole truth — possibly you. An unfair outcome can still be corrected, but only by facing the facts without flinching.'),
    (13, 'The Hanged Man', 'Major Arcana', 'XII', 'Surrender · New perspective · Pause · Sacrifice', 'Deliberate suspension that transforms a problem by changing the viewpoint.', 'The Hanged Man hangs willingly. Progress now comes through pausing, surrendering control and seeing the situation from an entirely new angle. What feels like stalling is actually deep preparation; the release you want follows the letting go.', 'Reversed, he is stuck — sacrifice without meaning, or martyrdom performed for an audience. The pause has become avoidance. Either commit to the new perspective or step down and move.'),
    (14, 'Death', 'Major Arcana', 'XIII', 'Transformation · Endings · Release · Rebirth', 'An ending that clears the ground for an inevitable rebirth.', 'Death rarely means literal death; it means transformation. Something — a role, a belief, a phase — has finished its work and must be released so the new can be born. Do not cling to the shed skin; what comes next cannot arrive while the door is barred.', 'Reversed, Death resisted. An ending is being prolonged out of fear, draining energy that renewal needs. The transition will happen either way; choosing it willingly restores your power.'),
    (15, 'Temperance', 'Major Arcana', 'XIV', 'Balance · Moderation · Alchemy · Patience', 'Opposites blended with care into something wiser than either alone.', 'Temperance is the art of blending. Extremes are tempered, conflicting needs find measure, and steady patient effort turns base metal to gold. Avoid excess in every direction; the middle path is not dull but precise.', 'Reversed, Temperance signals excess, impatience or a life out of balance. One ingredient is overwhelming the mixture — work, pleasure, worry or indulgence. Re-measure the proportions and let time do its quiet work.'),
    (16, 'The Devil', 'Major Arcana', 'XV', 'Bondage · Temptation · Shadow · Attachment', 'The chains we choose: attachments and appetites that quietly rule from below.', 'The Devil names the chain — a habit, a relationship, a fear — that pretends to be inescapable. The lock, however, opens from the inside. Look honestly at what binds you, especially what pleasure disguises, and the power of the bond will shrink on contact.', 'Reversed, the chains are loosening. Awareness of the attachment is breaking its grip, though withdrawal is real. Freeing yourself now is slow, unglamorous and entirely possible.'),
    (17, 'The Tower', 'Major Arcana', 'XVI', 'Upheaval · Revelation · Collapse · Awakening', 'Sudden, necessary collapse of a false structure.', 'The Tower strikes what was built on unstable ground. A shock, revelation or abrupt change topples assumptions, and the discomfort is proportional to how false the foundation was. Let it fall cleanly — what remains standing after the storm will be true.', 'Reversed, the Tower trembles. Disaster is feared or barely deferred; change is resisted until it must arrive all at once. Dismantle the weak structure voluntarily while demolition is still a choice.'),
    (18, 'The Star', 'Major Arcana', 'XVII', 'Hope · Renewal · Inspiration · Faith', 'Serenity and renewed faith after the storm has passed.', 'After the Tower, the Star. Healing water pours freely, inspiration returns, and a guiding light makes the long road feel walkable again. Hope is not naive here; it is accurate. Trust the quiet promise that you are being led somewhere kinder.', 'Reversed, the Star dims. Discouragement, disconnection or lost faith has you looking down instead of up. The light has not left the sky — only your gaze has dropped. Small acts of self-care restore the sight.'),
    (19, 'The Moon', 'Major Arcana', 'XVIII', 'Illusion · Dream · Anxiety · The unconscious', 'Moonlit fog: not everything is what it appears to be, and feelings amplify.', 'The Moon moves the reading into dream-logic. Fears magnify, facts blur, and intuition is needed precisely because the surface is unreliable. Do not force clarity at midnight; walk slowly, trust the deep currents, and wait for dawn to verify the shapes.', 'Reversed, the fog lifts. Confusion releases, a deception is uncovered, and nightmares lose their grip. Truth that was obscured is emerging — let it arrive the rest of the way.'),
    (20, 'The Sun', 'Major Arcana', 'XIX', 'Joy · Success · Vitality · Clarity', 'Warm, open success — everything visible, everything alive.', 'The Sun shines without subtlety: success, health, joy and simple truth. Achievements are seen and celebrated, relationships warm, and life feels briefly uncomplicated. Say yes to visibility; this is the card of being genuinely glad to be alive.', 'Reversed, the Sun is veiled. Joy is present but dimmed by delay, false modesty or residual clouds. The success is real; only the celebration is postponed. Let yourself receive the warmth that is already yours.'),
    (21, 'Judgement', 'Major Arcana', 'XX', 'Awakening · Reckoning · Calling · Renewal', 'A summons to rise, account for the past and answer a higher calling.', 'Judgement sounds the trumpet: an awakening, a calling, a moment of honest reckoning. The past returns not to punish but to be integrated. Forgive what must be forgiven, choose the higher path, and answer the call that has your true name on it.', 'Reversed, the call goes unanswered. Self-judgement masquerades as conscience, or old regrets block the rising. The summons will repeat; meeting it sooner is the mercy.'),
    (22, 'The World', 'Major Arcana', 'XXI', 'Completion · Wholeness · Achievement · Integration', 'The circle closes: completion, travel, and the whole world in your hands.', 'The World completes the great cycle. A significant chapter closes with mastery, integration and quiet triumph. Broad horizons open — literal travel, publishing, graduation, any finish line that becomes a gate. Dance once, then step through.', 'Reversed, the World awaits its final stitch. A project is 95 percent complete but the last closure is avoided, keeping the next gate shut. Finish the unfinished; completion is a skill, not an accident.'),
    (23, 'Ace of Wands', 'Wands', 'Ace', 'Spark · Initiative · Raw potential', 'A spark of pure enterprise waiting to be acted upon.', 'A new venture, job idea or creative spark ignites. The Ace of Wands is raw fuel — act on it quickly and boldly while the fire is fresh. Courage now pays for months ahead.', 'The match won''t strike: delay, doubt or a half-hearted start. The idea is good; the timing and the nerve need work. Rekindle it deliberately instead of blaming the spark.'),
    (24, 'Two of Wands', 'Wands', 'Two', 'Planning · Vision · First steps', 'The world in hand: choosing where to aim a fledgling enterprise.', 'The initial spark needs a map. The Two of Wands plans routes, weighs territories and makes the first bold commitment. Think bigger — the view from the battlements is wider than you assume.', 'Restlessness without a plan, or fear of leaving the known balcony. Small thinking shrinks a large vision. Name the destination and take one concrete step.'),
    (25, 'Three of Wands', 'Wands', 'Three', 'Expansion · Foresight · Ships coming in', 'Efforts launched are now visibly heading toward port.', 'What was set in motion is moving: expansion, cooperation from abroad, long-term plans proving sound. Look to the horizon and keep coordinating; your wider perspective is the asset.', 'Ships delayed, plans stalled by narrow vision or refusal to ask for help. Check whether you are waiting for a wind you could have made yourself.'),
    (26, 'Four of Wands', 'Wands', 'Four', 'Celebration · Homecoming · Milestone', 'A landing place: joy shared, a milestone genuinely reached.', 'Celebrate a real milestone — a launch, a reunion, a stable home base. The Four of Wands puts flowers on the gate. Pausing to mark progress is not lost time; it seals the foundation.', 'Celebration postponed or a transition that feels unsteady. Home and belonging may need repair before the next phase. Rebuild the welcome, then move.'),
    (27, 'Five of Wands', 'Wands', 'Five', 'Competition · Friction · Creative conflict', 'Busy, noisy struggle — rivalry that scrambles the energy.', 'Conflict, competition and clashing schedules tangle the day. The Five of Wands is sparring, not war: treat friction as practice, stay in the ring, and let creative tension sharpen rather than scatter you.', 'Conflict avoided until it leaks out sideways, or aggression without a target. Either name the fight honestly or withdraw gracefully — simmering serves no one.'),
    (28, 'Six of Wands', 'Wands', 'Six', 'Victory · Recognition · Public win', 'The triumphant return: recognition earned and visibly conferred.', 'A genuine win arrives with applause. The Six of Wands rides the laurel — promotion, praise, a bid accepted. Accept the recognition fully; confidence earned is meant to be worn.', 'Recognition withheld, imposter feelings, or a victory that feels hollow. Fall on your own sword privately if you must, but do not steal the credit that is due.'),
    (29, 'Seven of Wands', 'Wands', 'Seven', 'Defending position · Perseverance · Grit', 'Holding the high ground against challengers.', 'You are ahead, and others know it. The Seven of Wands defends territory with stubborn courage. Pick your battles deliberately, stand your ground on the important ones, and outlast the pushback.', 'Defence becomes overwhelm: too many fronts, exhaustion, temptation to abandon a defensible position. Consolidate, prioritize, and stop fighting ghosts.'),
    (30, 'Eight of Wands', 'Wands', 'Eight', 'Speed · Momentum · Rapid movement', 'Everything accelerates — messages, travel, fast forward motion.', 'The Eight of Wands is pure velocity: news arrives, flights book, replies land, and the project suddenly moves. Align with the speed and let the stream carry your work.', 'Delays, misdirected messages, scattered motion without progress. Slow down just enough to aim; speed without direction is only churn.'),
    (31, 'Nine of Wands', 'Wands', 'Nine', 'Resilience · Last stand · Battle fatigue', 'Wounded but standing: one last push with reserves nearly spent.', 'You are tired, wary and closer than you think. The Nine of Wands is perseverance with bruises — protect the perimeter, trust your experience, and finish what you started.', 'Paranoia and burnout distort the watch. Not every shadow is an enemy. Rest is a tactical necessity here, not a defeat.'),
    (32, 'Ten of Wands', 'Wands', 'Ten', 'Overload · Burden · Nearly done', 'Carrying everything at once, at the edge of capacity.', 'Responsibilities have piled into a bundle too large to see over. The Ten of Wands finishes the job by shouldering it — but afterwards, delegate or drop what was never yours to carry.', 'The load crushes: refusing help, resentment, or a goal that has become pure slog. Put the bundle down, sort it honestly, and pick up only what still matters.'),
    (33, 'Page of Wands', 'Wands', 'Page', 'Enthusiasm · Exploration · Good news', 'A young flame: curiosity, announcements and beginner excitement.', 'A burst of enthusiasm, often with news of an opportunity. The Page of Wands explores without guarantees — try the class, send the message, light the pilot flame and see what catches.', 'Enthusiasm that fizzles before commitment, or flaky messaging. The fire needs a real container: pick one direction and stay with it past the fun part.'),
    (34, 'Knight of Wands', 'Wands', 'Knight', 'Adventure · Boldness · Impulsive flight', 'Charging ahead with passion and little patience for detours.', 'Full gallop toward a vision. The Knight of Wands is charisma, bold travel and decisive — if occasionally reckless — action. Move now, refine later; momentum is your ally.', 'Recklessness, hasty exits, passion that burns through commitments. Land the horse: channel the fire into sustained direction or it will simply scatter.'),
    (35, 'Queen of Wands', 'Wands', 'Queen', 'Warmth · Confidence · Charismatic host', 'Self-assured warmth that inspires by sheer presence.', 'The Queen of Wands rules her hearth and her stage with magnetism. Lead socially, create generously, and trust your vibrant instincts — your energy literally warms and organizes the room.', 'Insecurity masked by bravado, or warmth withdrawn into jealousy. Recharge your own fire before lending or demanding anyone else''s.'),
    (36, 'King of Wands', 'Wands', 'King', 'Visionary leadership · Enterprise · Bold rule', 'Mastery of fire: entrepreneurial leadership with enduring vision.', 'The King of Wands builds empires and inspires loyalty. Lead from the front with clear vision, delegate with trust, and turn raw ambition into lasting institutions.', 'Domination instead of leadership, or vision dulled into hubris. Listen before decreeing; the best kings take counsel and still decide.'),
    (37, 'Ace of Cups', 'Cups', 'Ace', 'New love · Emotional opening · Overflow', 'The cup offered: a new emotional beginning overflowing with feeling.', 'Love, friendship or creative inspiration opens freshly. The Ace of Cups is the heart''s yes — receive it, express it, and let compassion lead. Emotional renewal is here and it is real.', 'The cup is tipped away: blocked feelings, guardedness or outpouring grief. Feelings are present but unexpressed. Create a safe channel before the heart reopens.'),
    (38, 'Two of Cups', 'Cups', 'Two', 'Partnership · Mutual attraction · Vows', 'Two hearts meeting as equals: union, pact or genuine rapport.', 'A true partnership forms — romantic, business or a cherished friendship. Mutual regard and shared vulnerability seal the deal. Say the honest word; the connection deepens through it.', 'Imbalance in the exchange: one heart leaning, one drifting. Trust needs repair or a relationship is out of tune. Re-negotiate the meeting point honestly.'),
    (39, 'Three of Cups', 'Cups', 'Three', 'Friendship · Community · Celebration', 'Joy shared among friends: community, celebration, creative kinship.', 'Gatherings, good news and the warmth of chosen family. The Three of Cups reminds you that joy multiplies when divided. Celebrate together and lean on your circle.', 'Gossip, third-party strain or celebration that excludes. A triangle complicates the circle. Clear the air directly rather than through the group''s chorus.'),
    (40, 'Four of Cups', 'Cups', 'Four', 'Apathy · Contemplation · Missed offer', 'A gift ignored while attention drifts inward.', 'Withdrawal and weariness: the world offers a cup and you are staring at the ground. Rest is legitimate, but look up before the offered opportunity walks past. Reassessment precedes re-engagement.', 'Re-awakening from the fog — reaching for the cup again. Old apathy lifts as new interests stir. Accept the invitation that recenters you.'),
    (41, 'Five of Cups', 'Cups', 'Five', 'Grief · Loss · Regret', 'Mourning what spilled, while a cup still stands behind you.', 'Loss and regret deserve honest grief. Yet the Five of Cups shows what remains upright: support, love and possibility survive the spilling. Turn, slowly, when you are ready.', 'Grief integrated; the turning has begun. Forgiveness — of self or other — releases the lingering residue. Walk home toward what still stands.'),
    (42, 'Six of Cups', 'Cups', 'Six', 'Nostalgia · Innocence · Reunion', 'Sweet memory and childhood warmth exchanged between two people.', 'The past visits gently: reunions, keepsakes, childlike delight. The Six of Cups offers innocence and simple kindness. Share memories, mentor someone, play without purpose.', 'Nostalgia becomes a locked room, or old patterns replay in new costumes. Live forward; take the sweetness and leave the sugar-crust.'),
    (43, 'Seven of Cups', 'Cups', 'Seven', 'Options · Fantasy · Illusion of choice', 'Seven glittering cups: imagination abundant, judgment required.', 'Dreams, daydreams and tempting possibilities multiply. Not all that glitters holds wine. Fantasy is fuel but discernment is the chalice — test the options against reality before you pour your life into one.', 'Clarity cuts through the fog: a choice becomes real, or a deception collapses. Commitment replaces browsing. Choose one cup and drink it fully.'),
    (44, 'Eight of Cups', 'Cups', 'Eight', 'Walking away · Deeper quest · Leaving the shallow', 'Turning from emotional comfort toward a harder, truer mountain path.', 'Something once valued no longer feeds you, however full it looks. The Eight of Cups walks away at night — gently, resolutely — toward meaning rather than comfort. Departure is the honest act here.', 'Retreat postponed: clinging to the familiar out of guilt or fear, drifting without truly staying. Either return wholeheartedly or complete the walk-out you keep rehearsing.'),
    (45, 'Nine of Cups', 'Cups', 'Nine', 'Contentment · Wish fulfilled · Satisfaction', 'The wish card: deep personal satisfaction, arms crossed in ease.', 'What you wanted arrives and it suits you. The Nine of Cups is emotional abundance, pleasure earned and savoured. Enjoy it openly — this is one of the deck''s cleanest yeses.', 'Smugness or surface pleasure masking an unfed heart. The wish was granted but not the need beneath it. Name the deeper want honestly.'),
    (46, 'Ten of Cups', 'Cups', 'Ten', 'Harmony · Family · Emotional completion', 'The rainbow home: lasting emotional fulfillment in family and tribe.', 'Peace that spreads beyond the self — family harmony, community joy, a long arc finally resolving into contentment. The Ten of Cups is the heart''s destination; build gently and guard it well.', 'The ideal family picture cracks: disconnection at home, or perfectionism ruining real intimacy. Repair happens through small daily cups, not grand images.'),
    (47, 'Page of Cups', 'Cups', 'Page', 'Message · Romantic spark · Creative whisper', 'A delicate fish in a cup: intuition, sweet messages, creative stirrings.', 'News of love, an artistic impulse, a gentle intuitive nudge. The Page of Cups invites play and openness — respond to the odd idea and the tender feeling; both carry water.', 'Emotional immaturity, moodiness or escapist fantasy. The inner child needs guidance, not silencing. Grow the feeling into words.'),
    (48, 'Knight of Cups', 'Cups', 'Knight', 'Romance · Idealism · The gracious quest', 'The romantic knight: charm, devotion and an offered chalice.', 'Romance and idealism ride in — proposals, heartfelt gestures, artistic opportunity. The Knight of Cups moves with feeling and style. Accept the invitation; follow the beauty.', 'Charm without follow-through, moody idealism, promises that dissolve at dawn. Ask for substance, not just roses — from yourself as much as others.'),
    (49, 'Queen of Cups', 'Cups', 'Queen', 'Compassion · Intuition · Emotional depth', 'The empath''s throne: deep feeling held with wisdom and discretion.', 'The Queen of Cups feels everything and drowns in nothing. Intuition, counselling, artistic depth and unconditional care flow through her. Trust your heart''s readings; hold boundaries kindly.', 'Overwhelm, codependence or intuition warped by fear. The cup overflows into anxiety. Ground yourself before absorbing anyone else''s weather.'),
    (50, 'King of Cups', 'Cups', 'King', 'Emotional mastery · Calm counsel · Diplomacy', 'Mastery of water: steady compassion that governs the deep.', 'The King of Cups rules the sea with calm — diplomacy, mature love, counsel given from experience. Balance reason and feeling; be the steady harbour others steer toward.', 'Emotional control turned cold, or turbulence leaking through a calm mask. Quiet manipulation must yield to honest speech before the sea calms.'),
    (51, 'Ace of Swords', 'Swords', 'Ace', 'Clarity · Breakthrough · Truth', 'The blade of truth: a piercing insight cuts through confusion.', 'A breakthrough of understanding arrives — sharp, clean, undeniable. The Ace of Swords wins by naming things exactly as they are. Speak the truth, make the decision, claim mental victory.', 'Clarity twisted into cruelty, or confusion persisting despite the facts. The sword can carve a path or cut a friend. Examine the intent behind the blade.'),
    (52, 'Two of Swords', 'Swords', 'Two', 'Stalemate · Difficult choice · Blindfold', 'Two blades crossed: a decision avoided behind a deliberate blindfold.', 'You are at an impasse, weighing two options with eyes closed. The Two of Swords counsels honest stillness — the information exists, but you must lower the blindfold and look at what you already know.', 'The blindfold slips: the truth moves and the stalemate breaks. Information surfaces that forces the decision. Choose with open eyes.'),
    (53, 'Three of Swords', 'Swords', 'Three', 'Heartbreak · Painful truth · Sorrow', 'The rain-soaked heart: grief that comes from seeing clearly.', 'A painful truth lands — heartbreak, betrayal, severance. The Three of Swords honours the wound rather than numbing it. Let the rain fall; clarity bought with pain is still clarity, and healing follows honesty.', 'Healing begins: the swords ease out, forgiveness loosens the barbs. Old wounds may throb in changed weather. Recovery is underway — keep it honest.'),
    (54, 'Four of Swords', 'Swords', 'Four', 'Rest · Recovery · Retreat', 'The knight at rest: strategic stillness to restore the mind.', 'Exhaustion demands rest before the next battle. The Four of Swords prescribes deliberate pause — sleep, silence, sanctuary. This is strategy, not surrender; the blade stays close.', 'Restlessness returns too soon, or rest has curdled into hiding. Re-enter the world gently; the mind is sharper for the pause you took.'),
    (55, 'Five of Swords', 'Swords', 'Five', 'Defeat · Pyrrhic victory · Hollow win', 'Winning the argument and losing the field.', 'Conflict ends with casualties. The Five of Swords asks whether the victory was worth its price — in trust, in reputation, in loneliness. If you won ugly, repair quickly; if you lost, withdraw with dignity.', 'The tide turns: amends made, grievances aired, old battles finally released. Let the grudge go — you have paid its rent long enough.'),
    (56, 'Six of Swords', 'Swords', 'Six', 'Passage · Transition · Moving on', 'The quiet ferry: leaving troubled waters for a steadier shore.', 'Movement away from turbulence toward calmer ground. The Six of Swords travels light and says little; the journey may be bittersweet but the direction is right. Steadier waters genuinely lie ahead.', 'Passage resisted: dragged baggage, unfinished goodbyes, or a return to rough seas. Cut the moorings cleanly — the ferry cannot sail while tied.'),
    (57, 'Seven of Swords', 'Swords', 'Seven', 'Strategy · Stealth · Questionable tactics', 'Taking what isn''t watched: cunning that risks the truth it serves.', 'Strategy favours the nimble: act with discretion, guard your plans, move before others expect. But the Seven of Swords carries a caution — tactics that deceive will cost more than they gain.', 'The stealth exposed: confession, discovery, or the decision to stop scheming. Truth-telling rebuilds what cunning eroded. Come clean and keep your honour.'),
    (58, 'Eight of Swords', 'Swords', 'Eight', 'Restriction · Self-imposed limits · Fear', 'Bound and blindfolded — yet the bindings are looser than they feel.', 'Feeling trapped by circumstances, stories or fears that barely bind in reality. The Eight of Swords invites one small step outside the pattern; the prison door has been unlatched for some time.', 'The bands fall: new options, freed thinking, courage returning. Mental chains break quickly once challenged. Walk out while the way is open.'),
    (59, 'Nine of Swords', 'Swords', 'Nine', 'Anxiety · Nightmares · Worry at 3am', 'The 3 a.m. mind: fears magnified in the dark.', 'Worry runs the night shift. The Nine of Swords dramatizes fears that shrink in daylight. Get the worries onto paper, share them with someone warm, and wait for morning before believing the worst.', 'The dawn comes: anxiety eases, help accepted, the night''s terrors re-sized to their true scale. Speaking the fear was the beginning of its end.'),
    (60, 'Ten of Swords', 'Swords', 'Ten', 'Rock bottom · Ending · The worst has passed', 'The fallen figure: an ending so complete that only dawn remains.', 'An ending arrives in full — painful, public, undeniable. The Ten of Swords promises that this is the bottom; nothing more falls. Dawn is already in the frame. Rest, then rise into the chapter that starts without the old weight.', 'Recovery from the depths: gradual mending, resistance to victimhood, lessons harvested. The worst has truly passed when you stop reliving it.'),
    (61, 'Page of Swords', 'Swords', 'Page', 'Curiosity · Vigilance · New learning', 'The watchful student: sharp curiosity and words worth heeding.', 'Study, messages and mental alertness. The Page of Swords watches, asks questions and keeps notes. Learn the tools of clear thinking now; a watchful mind catches what others miss.', 'Gossip, sharp words or learning without discipline. Watch the tongue as carefully as the facts. Curiosity serves when it is aimed.'),
    (62, 'Knight of Swords', 'Swords', 'Knight', 'Ambition · Haste · Charging intellect', 'The charging mind: fast, fierce and sometimes ahead of itself.', 'Bold mental thrust — debate, fast decisions, urgent pursuit of a cause. The Knight of Swords accomplishes much by moving first. Just ensure the target is worth the charge.', 'Burnout and battle-scarred opinions: aggression replacing argument. Slow the horse, check the map, and let precision outrun fury.'),
    (63, 'Queen of Swords', 'Swords', 'Queen', 'Perception · Independence · Clear boundaries', 'The clear-eyed judge: perception honed by experience, edges intact.', 'The Queen of Swords sees through pretense with lived wisdom. Speak with precision, keep healthy boundaries, and value truth over comfort. Her clarity is a gift to those ready for it.', 'Bitterness sharpens perception into judgment. Old wounds color the lens. Grieve what hardened you, and the blade stays bright instead of brittle.'),
    (64, 'King of Swords', 'Swords', 'King', 'Intellectual authority · Ethics · Decisive mind', 'Mastery of air: principled judgment from the seat of authority.', 'The King of Swords rules with intellect, ethics and impartial rigor. Make the hard ruling, articulate the standard, lead with objective truth. Logic in service of justice is his crown.', 'Dogma, coldness or intellect used as a weapon. When heads rule hearts absolutely, judgment loses its justice. Reintegrate the human beneath the crown.'),
    (65, 'Ace of Pentacles', 'Pentacles', 'Ace', 'Opportunity · Seed money · Manifestation', 'The coin in hand: a tangible new opportunity takes root.', 'A concrete opportunity appears — a job, a contract, funding, a healthy new habit. The Ace of Pentacles is the seed of real-world success. Plant it in good soil and tend it patiently.', 'The seed drops from the hand: missed opportunity, poor planning or scarcity thinking. Prosperity needs a vessel. Prepare the ground before blaming the season.'),
    (66, 'Two of Pentacles', 'Pentacles', 'Two', 'Juggling · Adaptability · Balance in motion', 'Two coins dancing: keeping multiple commitments airborne with rhythm.', 'Multiple demands, all manageable with nimble scheduling. The Two of Pentacles juggles work, home and play without dropping the beat. Flexibility is the skill; prioritize by the hour, not by the year.', 'The juggle collapses: overcommitment, endless reshuffling without progress. Put one ball down on purpose. Balance means choosing what not to hold.'),
    (67, 'Three of Pentacles', 'Pentacles', 'Three', 'Craftsmanship · Teamwork · Mastery in progress', 'The cathedral workshop: skill honoured, plans shared, work that lasts.', 'Collaboration and craft: your competence is recognized and the team builds well together. The Three of Pentacles rewards training, feedback and pride in measurable work. Build to be inspected.', 'Mediocrity tolerated, teamwork fraying, or talents undervalued. Raise the standard or renegotiate the role — skilled hands deserve skilled company.'),
    (68, 'Four of Pentacles', 'Pentacles', 'Four', 'Security · Control · Holding tight', 'The cautious holder: security cherished, gates kept shut.', 'Consolidate what you have: savings, boundaries, a stable base. The Four of Pentacles protects hard-won gains. Prudence is wise now — just check the vault has a door that opens from inside.', 'Grip tightens into stagnation: hoarding money, feelings or control. Security that costs every exchange is a cell. Loosen one finger at a time.'),
    (69, 'Five of Pentacles', 'Pentacles', 'Five', 'Hardship · Exclusion · Winter road', 'Two souls in the snow: hard times felt most sharply in isolation.', 'Lean months — financial, physical or spiritual. The Five of Pentacles walks past the lit window: help exists but pride or despair hides it. Ask; the church door is rarely locked.', 'The cold eases: recovery, employment found, belonging restored. Hardship ends gradually and then suddenly. Accept the hand that is already extended.'),
    (70, 'Six of Pentacles', 'Pentacles', 'Six', 'Generosity · Exchange · Fair sharing', 'Scales in one hand, coin in the other: giving and receiving in balance.', 'Resources circulate: a raise, a gift, charity given or received with dignity. The Six of Pentacles keeps the scales honest — generosity with clear terms feeds everyone, including the giver.', 'Strings attached, charity that controls, or debt that distorts a relationship. Re-balance the scales; true generosity has no ledger.'),
    (71, 'Seven of Pentacles', 'Pentacles', 'Seven', 'Patience · Assessment · Long game', 'Pausing on the vine: growth underway that cannot be rushed.', 'Effort is invested and fruit is forming, slowly. The Seven of Pentacles is the farmer''s pause — assess, prune, and let time compound. Patience here is active, not passive.', 'Impatience or wasted investment: effort poured into soil that won''t yield. Audit honestly. Sometimes the wisest harvest is knowing what to stop watering.'),
    (72, 'Eight of Pentacles', 'Pentacles', 'Eight', 'Diligence · Apprenticeship · Craft repetition', 'Head down, hammer up: mastery built one deliberate repetition at a time.', 'Focused work refines skill. The Eight of Pentacles loves the process itself — practice, detail, incremental excellence. Show up at the workbench; the masterpiece is cumulative.', 'Perfectionism or drudgery: the craft has lost its meaning, or quality is slipping under rushed hands. Reconnect with why the work matters or refresh the method.'),
    (73, 'Nine of Pentacles', 'Pentacles', 'Nine', 'Independence · Self-made comfort · Refinement', 'The gracious estate: earned independence and refined enjoyment.', 'Self-reliance pays off: comfort, discipline rewarded, a life designed on your own terms. The Nine of Pentacles enjoys solitude and luxury without apology. Savour what your consistent effort built.', 'Gilded loneliness or over-investment in image: success that costs connection, or comfort that dulls growth. Money buys freedom when it also buys time with people you love.'),
    (74, 'Ten of Pentacles', 'Pentacles', 'Ten', 'Legacy · Wealth · Enduring foundation', 'The family arch: lasting wealth, tradition and legacy beyond the self.', 'Long-term establishment: family prosperity, a business matured, a legacy taking shape. The Ten of Pentacles thinks in generations. Build institutions and traditions that outlive the quarter.', 'Legacy disputes, tradition turned rigid, or wealth without roots. What is inherited must also be renewed. Tend the family tree, not just its fruit.'),
    (75, 'Page of Pentacles', 'Pentacles', 'Page', 'Study · Manifesting goals · Student''s coin', 'The eager student: practical learning and a tangible new goal.', 'A new course, certification, side-hustle or savings plan. The Page of Pentacles is humble, focused and delighted by small real progress. Begin the practical education; results follow repetition.', 'Distraction from study, unrealistic plans, or procrastination dressed as research. The coin rewards showing up. Shrink the goal until starting is easy.'),
    (76, 'Knight of Pentacles', 'Pentacles', 'Knight', 'Reliability · Methodical progress · Unhurried strength', 'The steady rider: slow, thorough, unstoppable progress.', 'Routine, patience and thoroughness win the long race. The Knight of Pentacles delivers — unfashionably perhaps, but completely. Trust the methodical pace; boredom is the price of reliability.', 'Stagnation or stubbornness: motion reduced to routine, or workaholic dullness missing life''s invitations. A little risk fertilizes the field.'),
    (77, 'Queen of Pentacles', 'Pentacles', 'Queen', 'Nurture · Practicality · Abundant home', 'The garden queen: practical nurturing that makes resources flourish.', 'The Queen of Pentacles feeds body and household alike — generous, grounded, superbly competent. Care expressed through tangible means: good food, sound finances, a welcoming home. Prosperity grows around her.', 'Self-neglect behind everyone else''s comfort, or money worries shadowing generosity. The garden needs the gardener fed. Include yourself in your own care.'),
    (78, 'King of Pentacles', 'Pentacles', 'King', 'Prosperity · Stewardship · Mastery of the material', 'The vine-wrapped throne: wealth mastered and wisely stewarded.', 'Mastery of the material world: enterprise matured, resources grown, dependents secured. The King of Pentacles leads with proven competence and quiet generosity. Steward well; abundance is a responsibility.', 'Greed, rigidity or status worship: wealth hoarded while trust erodes. Prosperity divorced from purpose hollows out. Invest in what money cannot buy.')
) s ON t.CARD_ID = s.CARD_ID AND t.LANGUAGE_CODE = 'en'
WHEN MATCHED THEN UPDATE SET NAME = s.NAME, ARCANA = s.ARCANA, RANK = s.RANK, KEYWORDS = s.KEYWORDS,
    MEANING = s.MEANING, UPRIGHT = s.UPRIGHT, REVERSED = s.REVERSED
WHEN NOT MATCHED THEN INSERT (CARD_ID, LANGUAGE_CODE, NAME, ARCANA, RANK, KEYWORDS, MEANING, UPRIGHT, REVERSED)
    VALUES (s.CARD_ID, 'en', s.NAME, s.ARCANA, s.RANK, s.KEYWORDS, s.MEANING, s.UPRIGHT, s.REVERSED);
